command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GRAUSAMES SPIEL (Aphasma)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.1tBOnhW6okOKlMd4");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. WIRKENDEN PRÜFEN & QS HOLEN ---
    let casterToken = canvas.tokens.controlled[0];
    const casterActor = casterToken?.actor || game.user.character;

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus, liebes Ahnenkind!");
    }

    if (!casterToken) {
        casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);
    }

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) {
        await casterActor.unsetFlag("world", "letzteGabenQS"); 
    }
    if (typeof testData !== "undefined" && testData) {
        qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);
    }

    const gabenName = "Grausames Spiel";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // --- 3. ZIEL PRÜFEN ---
    let targetToken = game.user.targets.first();
    if (!targetToken) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte markiere (Target) zuerst das Token deines Ziels!");
    }
    let targetActor = targetToken.actor;
    if (!targetActor) {
        return ui.notifications.warn("Das gewählte Ziel hat keinen gültigen Charakterbogen!");
    }
    if (casterActor.id === targetActor.id) {
        return ui.notifications.warn("Luna sagt 🌙: Du kannst das grausame Spiel nicht an dir selbst wirken!");
    }

    // --- REICHWEITEN-PRÜFUNG (8 Schritt) ---
    if (casterToken && targetToken && DSK_FW.Distanz) {
        const dist = DSK_FW.Distanz(casterToken, targetToken);
        if (dist > 8) {
            return ui.notifications.warn(`Luna sagt 🌙: Ziel verfehlt! ${targetToken.name} ist zu weit entfernt! (Reichweite: 8 Schritt, aktuelle Distanz: ${Math.round(dist)} Schritt)`);
        }
    }

    // --- LEBEWESEN-PRÜFUNG ---
    const actorType = (targetActor.type || "").toLowerCase();
    const species = (targetActor.system?.species?.value || targetActor.system?.details?.species || "").toLowerCase();
    const excludedWords = ["untot", "geist", "vampir", "leiche", "golem", "skelett", "zombie", "dämon", "homunkulus", "mumie"];

    if (excludedWords.some(w => species.includes(w)) || actorType === "spirit") {
        return ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                ${DSK_FW.UI.Header(finalEffektName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="color:#b30000; font-weight:bold;">Wirkung verpufft!</p>
                    <p><b>${targetActor.name}</b> ist kein Lebewesen. Das grausame Spiel findet hier kein Blut zum Vergießen.</p>
                </div>
            `
        });
    }

    // --- 4. LeP VERGLEICH (Ziel muss weniger LeP haben als der Wirkende) ---
    const casterLeP = foundry.utils.getProperty(casterActor, "system.stats.LeP.value") || 0;
    const targetLeP = foundry.utils.getProperty(targetActor, "system.stats.LeP.value") || 0;

    if (targetLeP >= casterLeP) {
        return ChatMessage.create({
            speaker: { alias: "System" },
            content: `
                ${DSK_FW.UI.Header(finalEffektName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="color:#b30000; font-weight:bold; font-size:1.1em;">Aphasma verweigert das Spiel!</p>
                    <p>Dein Ziel muss schwächer sein als du. <br><b>${targetActor.name}</b> (${targetLeP} LeP) hat jedoch nicht weniger Lebenspunkte als <b>${casterName}</b> (${casterLeP} LeP).</p>
                    <p style="font-size:0.9em; color:#555; margin-top:8px;"><i>Die Kraft der Ahnin schwindet wirkungslos.</i></p>
                </div>
            `
        });
    }

    // --- 5. SCHADEN BERECHNEN UND ANWENDEN ---
    const bonus = qsWert * 2;
    const schadensWurf = new Roll(`2d6 + ${bonus}`);
    await schadensWurf.evaluate({ async: true });
    const gesamtSchaden = schadensWurf.total;

    // Aphasmas Grenze (5 LeP) exakt berechnen
    let tatsaechlicherSchaden = gesamtSchaden;
    let verpuffterSchaden = 0;
    let limitErreicht = false;

    if (targetLeP - gesamtSchaden < 5) {
        limitErreicht = true;
        if (targetLeP <= 5) {
            tatsaechlicherSchaden = 0;
        } else {
            tatsaechlicherSchaden = targetLeP - 5;
        }
        verpuffterSchaden = gesamtSchaden - tatsaechlicherSchaden;
    }

    let neueLeP = targetLeP - tatsaechlicherSchaden;

    // Schaden austeilen (nur wenn wirklich Schaden entsteht)
    if (tatsaechlicherSchaden > 0) {
        await targetActor.update({ "system.stats.LeP.value": neueLeP });
    }

    // --- 6. NACHRICHTEN AUSGEBEN (GETRENNT!) ---

    // Flüster-Empfänger bestimmen (Nur GM und der Spieler des Ahnenkindes)
    const getOwners = (act) => {
        if (!act) return [];
        const ownership = act.ownership || act.permission || {};
        return Object.entries(ownership).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
    };
    let whisperOwnerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => whisperOwnerIds.add(id));
    let whisperTargets = Array.from(whisperOwnerIds).filter(id => game.users.get(id));

    // A) Schadenswürfel geflüstert in den Chat posten
    await schadensWurf.toMessage({
        speaker: { alias: "System" },
        flavor: `<b>${finalEffektName}</b><br>Schaden gegen ${targetActor.name} (Bonus: QS ${qsWert} x 2)`,
        whisper: whisperTargets
    });

    // B) Öffentliche Karte (nur Flavour)
    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
            ${DSK_FW.UI.Header(finalEffektName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px; text-align:center;">
                <p><b>${casterName}</b> webt ein grausames Spiel gegen <b>${targetActor.name}</b>!</p>
                <hr>
                <p style="font-size:0.95em; line-height:1.35;">
                    Eine Vielzahl kleiner, unerklärlicher Risse und innerer Blutungen durchziehen den Körper des Opfers.
                </p>
            </div>
        `
    });

    // C) Geflüsterte Detail-Karte (Mechanik & LeP)
    let limitInfoHTML = "";
    if (limitErreicht) {
        limitInfoHTML = `
            <div style="margin-top: 10px; background: rgba(179, 0, 0, 0.1); border-left: 3px solid #b30000; padding: 6px; font-size: 0.9em; text-align: left;">
                <b style="color:#b30000;">Aphasmas Grenze erreicht!</b><br>
                Das Ziel hatte noch ${targetLeP} LeP. Es konnten daher nur <b>${tatsaechlicherSchaden} LeP</b> abgezogen werden.<br>
                Der restliche Schaden von <b>${verpuffterSchaden} TP</b> verfliegt wirkungslos! Die Gabe macht bei diesem Ziel keinen Sinn mehr.
            </div>
        `;
    }

    await ChatMessage.create({
        speaker: { alias: "System" },
        whisper: whisperTargets,
        content: `
            ${DSK_FW.UI.Header(finalEffektName + " (Details)", DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px; text-align:center;">
                <p style="font-size:1.15em; font-weight:bold; color:#8b0000; margin-top:8px;">
                    ${tatsaechlicherSchaden} Schadenspunkte erlitten!
                </p>
                <p style="font-size:0.85em; color:#555;">
                    <i>Aktuelle LeP von ${targetActor.name}: ${neueLeP}</i>
                </p>
                ${limitInfoHTML}
            </div>
        `
    });

})();
